<?php require_once __DIR__.'/backend/conexion.php';$q=trim($_GET['q']??'');$cat=trim($_GET['categoria']??'');$min=$_GET['min']??'';$max=$_GET['max']??'';$order=$_GET['orden']??'recientes';$sort=['precio_asc'=>'precio ASC','precio_desc'=>'precio DESC','nombre'=>'nombre ASC','recientes'=>'id DESC'][$order]??'id DESC';$sql='SELECT id,nombre,descripcion,precio,stock,imagen,categoria FROM productos WHERE activo=1';$args=[];if($q!==''){$sql.=' AND (nombre LIKE ? OR descripcion LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}if($cat!==''){$sql.=' AND categoria=?';$args[]=$cat;}if($min!==''){$sql.=' AND precio>=?';$args[]=(float)$min;}if($max!==''){$sql.=' AND precio<=?';$args[]=(float)$max;}$sql.=' ORDER BY '.$sort.' LIMIT 100';$st=$pdo->prepare($sql);$st->execute($args);$products=$st->fetchAll();$cats=$pdo->query('SELECT DISTINCT categoria FROM productos WHERE activo=1 ORDER BY categoria')->fetchAll(PDO::FETCH_COLUMN);function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function image_url($v){$v=trim((string)$v);if($v==='')return 'https://placehold.co/600x600?text=Producto';if(str_starts_with($v,'//'))return 'https:'.$v;if(preg_match('~^https?://~i',$v))return $v;if(preg_match('~^(?:javascript|data|vbscript):~i',$v))return 'https://placehold.co/600x600?text=Producto';return $v;}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Catálogo | Xiaomi Store Arequipa</title><link rel="stylesheet" href="styles.css"><style>.catalog{max-width:1200px;margin:30px auto;padding:18px}.filters{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.filters input,.filters select{padding:11px;border:1px solid #ddd;border-radius:8px}.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:18px}.pcard{background:white;border:1px solid #eee;border-radius:14px;padding:15px}.pcard img{width:100%;height:190px;object-fit:contain}.pcard a{color:inherit;text-decoration:none}.pcard strong{color:#d32f2f}</style></head><body><header style="background:#171717;color:white;padding:18px 5%"><a style="color:white" href="index.php">Xiaomi Store Arequipa</a></header><main class="catalog"><h1>Catálogo de productos</h1><form class="filters"><input name="q" placeholder="Buscar producto" value="<?=h($q)?>"><select name="categoria"><option value="">Todas las categorías</option><?php foreach($cats as $c):?><option <?=($cat===$c?'selected':'')?> value="<?=h($c)?>"><?=h($c)?></option><?php endforeach?></select><input name="min" type="number" step="0.01" placeholder="Precio mínimo" value="<?=h($min)?>"><input name="max" type="number" step="0.01" placeholder="Precio máximo" value="<?=h($max)?>"><select name="orden"><option value="recientes">Más recientes</option><option value="precio_asc" <?=$order==='precio_asc'?'selected':''?>>Precio menor</option><option value="precio_desc" <?=$order==='precio_desc'?'selected':''?>>Precio mayor</option><option value="nombre" <?=$order==='nombre'?'selected':''?>>Nombre</option></select><button>Filtrar</button></form><p><?=count($products)?> productos encontrados · <a href="comparar.php">Abrir comparador</a></p><section class="cards"><?php foreach($products as $x):?><article class="pcard"><a href="producto.php?id=<?=$x['id']?>"><img src="<?=h(image_url($x['imagen']))?>" alt="<?=h($x['nombre'])?>" loading="lazy" onerror="this.onerror=null;this.src='https://placehold.co/600x600?text=Producto'"><h3><?=h($x['nombre'])?></h3><p><?=h($x['descripcion'])?></p><strong>S/ <?=number_format($x['precio'],2)?></strong></a><p><?=((int)$x['stock']>0?'En stock':'Agotado')?></p><a href="producto.php?id=<?=$x['id']?>">Ver detalle →</a> <button type="button" data-compare="<?=$x['id']?>">Comparar</button></article><?php endforeach?></section></main><script src="js/comparador.js"></script></body></html>
